async function refresh(){if(busy)return;busy=true;const button=$("refresh");if(button){button.disabled=true;button.textContent="刷新中…";}try{await refreshStatus();if(currentPage==="projects")await refreshProjects();if(currentPage==="nodes")await refreshNodes();if(currentPage==="tasks")await refreshTasks();if(currentPage==="activity")await Promise.all([refreshMetrics(),refreshActivity()]);if(currentPage==="operations")await refreshOperations();if(currentPage==="config")await refreshConfig();}catch(error){setConnection(false);setText("status-title","暂时无法获取状态");setText("status-detail",error.message);}finally{busy=false;if(button){button.disabled=false;button.textContent="立即刷新";}}}
async function refreshForEvents(types){try{const tasks=[];if(types.has("job_changed"))tasks.push(refreshStatus());if(currentPage==="activity"){if(types.has("metrics_changed")||types.has("activity_changed")||types.has("job_changed"))tasks.push(refreshMetrics());if(types.has("activity_changed")||types.has("job_changed"))tasks.push(refreshActivity());}if(currentPage==="operations"&&types.has("operation_created"))tasks.push(refreshOperations());if(currentPage==="tasks"&&(types.has("job_changed")||types.has("operation_created")))tasks.push(refreshTasks());if(currentPage==="projects"){if(types.has("config_changed"))tasks.push(refreshProjects());else if(types.has("job_changed")||types.has("operation_created"))tasks.push(refreshProjectStates());}if(currentPage==="config"&&types.has("config_changed"))tasks.push(refreshConfig());if(currentPage==="config"&&(types.has("storage_changed")||types.has("job_changed")))tasks.push(refreshStorage());await Promise.all(tasks);}catch(error){setConnection(false,"事件刷新失败");}}
