async function handleAddProject(event){event.preventDefault();const form=event.currentTarget,path=$("add-project-path").value.trim(),project=$("add-project-id").value.trim(),workspace=$("add-project-workspace").value,profile=$("add-project-profile").value,write=$("add-project-write").checked,exec=$("add-project-exec").checked,commit=$("add-project-commit").checked,mutation=$("add-project-git-mutation").checked,push=$("add-project-git-push").checked;if(!workspace){setWriteStatus("请选择 Workspace","error");return;}if(!path){setWriteStatus("Absolute Path 不能为空","error");return;}if(!path.startsWith("/")){setWriteStatus("Absolute Path 必须是绝对路径","error");return;}if(project&&!/^[A-Za-z0-9_-]{1,64}$/.test(project)){setWriteStatus("Project ID 只能包含字母、数字、_、-，最长 64 个字符","error");return;}if((exec||commit)&&!write){setWriteStatus("exec / commit 需要 write","error");return;}if(mutation&&(!write||!exec)){setWriteStatus("git rw 需要 write + exec","error");return;}const button=form.querySelector("button[type=submit]");button.disabled=true;button.textContent="保存中…";setWriteStatus("正在写入 config.toml…","pending");try{const result=await sendJson("/api/projects","POST",{expected_revision:configRevision,workspace,project:project||null,path,allow_write:write,allow_exec:exec,allow_git_commit:commit,allow_git_mutation:mutation,allow_git_push:push,execution_profile:profile});$("add-project-id").value="";$("add-project-path").value="";const target=`${result.project?.workspace||workspace}/${result.project?.id||project||"project"}`;setWriteStatus(result.requires_restart?`已保存 ${target}，但热重载未生效：${result.reload_warning||"需要重启 EndlessVibe"}`:`已保存 ${target} 并已热生效`,result.requires_restart?"pending":"success");await refreshProjects();}catch(error){const message=error.status===409?"配置已变化，已刷新，请重新填写后保存":error.message;setWriteStatus(`保存失败：${message}`,"error");if(error.status===409)await refreshProjects();}finally{button.disabled=false;button.textContent="保存并添加";}}
