async function handleSandboxCheck(){const button=$("sandbox-check"),status=$("sandbox-check-status");if(!button)return;button.disabled=true;button.textContent="Checking…";if(status){status.textContent="正在创建基础 bubblewrap namespace 并检查工具可见性…";status.className="write-status pending";}try{const data=await getJson("/api/sandbox");renderSandboxDiagnostics(data);const missing=(data.diagnostics?.programs||[]).filter(p=>p.required&&p.status!=="available");if(status){status.textContent=missing.length?`缺失 required programs: ${missing.map(p=>p.program).join(", ")}`:"Sandbox required programs 可见";status.className=`write-status ${missing.length?"error":"success"}`;}}catch(error){if(status){status.textContent=`Sandbox diagnostics 失败：${error.message}`;status.className="write-status error";}}finally{button.disabled=false;button.textContent="Check Sandbox";}}
async function handleStorageCacheCleanup(){const button=$("storage-cache-cleanup");if(!button||button.disabled)return;const estimate=$("storage-exec-size")?.textContent||"未知大小";if(!window.confirm(`确认清空执行缓存（已扫描 ${estimate}）？\n\n仅删除 EndlessVibe 状态目录中的 exec-cache。构建产物/工具缓存会丢失，下一次编译需重新生成；不会删除项目文件、Git 仓库、Backups 或 SQLite 数据。\n\n正在运行 Job 时服务器会拒绝清理。`))return;storageActionBusy=true;button.disabled=true;$("storage-compact")&&( $("storage-compact").disabled=true );button.textContent="Clearing cache…";setSettingsEditorStatus("storage-cleanup-status","清理执行缓存中，请勿关闭页面或启动新 Job…","pending");try{const result=await sendJson("/api/storage/cleanup","POST",{scope:"exec_cache",confirmation:"CLEAR_EXEC_CACHE"});setSettingsEditorStatus("storage-cleanup-status",`执行缓存清理完成：已移除 ${result.removed_top_level_entries??0} 个顶层项，估计清理至少 ${formatBytes(result.estimated_reclaim_bytes_at_least??0)}。后续构建需要重新生成。`,"success");}catch(error){setSettingsEditorStatus("storage-cleanup-status",error.status===409?"缓存当前被 Job 使用，待所有 Job 完成后重试":`缓存清理失败：${error.message}（如果部分完成，请刷新容量）`,"error");}finally{storageActionBusy=false;button.textContent="Clear execution cache";await refreshStorage().catch(()=>{});}}
async function handleStorageCompact(){const button=$("storage-compact");if(!button||button.disabled)return;if(!window.confirm("确认整理 SQLite？先清理超过保留策略的记录，再执行 SQLite VACUUM 和 WAL checkpoint。这个操作可能短暂占用磁盘与数据库锁，且不会清除 exec-cache。"))return;storageActionBusy=true;button.disabled=true;$("storage-cache-cleanup")&&( $("storage-cache-cleanup").disabled=true );button.textContent="Compacting…";setSettingsEditorStatus("storage-cleanup-status","正在清理过期记录并压缩 SQLite…","pending");try{const result=await sendJson("/api/storage/compact","POST",{});setSettingsEditorStatus("storage-cleanup-status",`SQLite 已压缩，逻辑空间减少 ${formatBytes(result.compaction?.reclaimed_logical_bytes??0)}，记录清理 ${result.maintenance?.deleted?.total??0} 条。`,"success");}catch(error){setSettingsEditorStatus("storage-cleanup-status",error.status===409?"有运行中的 Job，数据库压缩需在空闲时执行":`SQLite 压缩失败：${error.message}`,"error");}finally{storageActionBusy=false;button.textContent="Compact SQLite";await refreshStorage().catch(()=>{});}}
async function handleStorageMaintenance(){const button=$("storage-maintenance"),status=$("storage-maintenance-status");if(!button)return;button.disabled=true;button.textContent="Maintaining…";if(status){status.textContent="正在执行受限 retention cleanup…";status.className="write-status pending";}try{const result=await sendJson("/api/storage/maintenance","POST",{});if(status){status.textContent=`已完成：删除 ${result.deleted?.total??0} 条记录；未执行 VACUUM`;status.className="write-status success";}await refreshStorage();}catch(error){if(status){status.textContent=`Maintenance 失败：${error.message}`;status.className="write-status error";}}finally{button.disabled=false;button.textContent="Prune records";}}
async function handleConfigReload(){const button=$("config-reload");if(!button)return;button.disabled=true;button.textContent="Reloading…";setReloadStatus("正在重新验证并加载 Workspace / Project 授权…","pending");try{const result=await sendJson("/api/config/reload","POST",{});setReloadStatus(`已热重载 config revision ${String(result.revision||"").slice(0,12)} · ${result.workspace_count??0} workspaces · ${result.project_count??0} projects`,"success");await Promise.all([refreshConfig(),refreshStatus()]);}catch(error){setReloadStatus(error.code==="RELOAD_RESTART_REQUIRED"?`无法热重载：${error.message}`:`Reload 失败：${error.message}`,"error");await refreshConfig().catch(()=>{});}finally{button.disabled=false;button.textContent="Reload project config";}}
activatePage();initNodes();setText("site-origin",location.origin);
$("refresh")?.addEventListener("click",refresh);
$("add-project-form")?.addEventListener("submit",handleAddProject);
$("workspace-config")?.addEventListener("submit",handlePermissionSubmit);
$("config-reload")?.addEventListener("click",handleConfigReload);
$("readonly-mount-add")?.addEventListener("click",addReadonlyMount);
$("git-editor")?.addEventListener("submit",handleGitSave);
$("docker-editor")?.addEventListener("submit",handleDockerSave);
$("docker-editor")?.addEventListener("input",()=>{dockerEditorDirty=true;setSettingsEditorStatus("docker-editor-status","Docker 安全配置有未保存的修改","pending");});
$("limits-editor")?.addEventListener("submit",handleLimitsSave);
$("git-editor")?.addEventListener("input",()=>{gitEditorDirty=true;setSettingsEditorStatus("git-editor-status","Git 配置有未保存的更改","pending");});
$("limits-editor")?.addEventListener("input",()=>{limitsEditorDirty=true;setSettingsEditorStatus("limits-editor-status","Limits 有未保存的更改","pending");});
$("readonly-mount-save")?.addEventListener("click",handleReadonlyMountSave);
$("readonly-mount-list")?.addEventListener("input",()=>{mountEditorDirty=true;setMountStatus("有未保存的 readonly mount 修改","pending");});
$("sandbox-check")?.addEventListener("click",handleSandboxCheck);
$("storage-maintenance")?.addEventListener("click",handleStorageMaintenance);
$("storage-cache-cleanup")?.addEventListener("click",handleStorageCacheCleanup);
$("storage-compact")?.addEventListener("click",handleStorageCompact);
$("expand-all-operations")?.addEventListener("click",expandAllOperations);
$("collapse-all-operations")?.addEventListener("click",collapseAllOperations);
document.addEventListener("visibilitychange",()=>{if(!document.hidden&&hiddenDirty){hiddenDirty=false;pendingEvents.clear();refresh();}});
window.addEventListener("online",()=>{refresh();if(!eventSource||eventSource.readyState===EventSource.CLOSED)connectEvents();});
window.addEventListener("beforeunload",()=>eventSource?.close());
if("ResizeObserver"in window)new ResizeObserver(resizePlots).observe(document.querySelector(".shell"));else window.addEventListener("resize",resizePlots);
setInterval(()=>{if(serviceOnline&&uptimeReceivedAt)setText("uptime",formatUptime(uptimeSnapshot+Math.floor((Date.now()-uptimeReceivedAt)/1000)));},1000);
refresh().finally(connectEvents);
